// URP Dissolve - Fragment shader core
half4 noise = SAMPLE_TEXTURE2D(_NoiseTex, sampler_NoiseTex, IN.uv);
clip(noise.r - _DissolveAmount);

half edgeFactor = saturate((noise.r - _DissolveAmount) / _EdgeWidth);
half4 edgeColor = lerp(_EdgeColor, half4(0,0,0,0), edgeFactor);
half4 baseColor = SAMPLE_TEXTURE2D(_BaseMap, sampler_BaseMap, IN.uv);
return baseColor + edgeColor * (1.0 - edgeFactor);

// URP Outline - Vertex extrusion pass
float3 normalWS = TransformObjectToWorldNormal(v.normalOS);
float3 posWS = TransformObjectToWorld(v.positionOS.xyz);
posWS += normalWS * _OutlineWidth * 0.01;

o.positionCS = TransformWorldToHClip(posWS);
o.color = _OutlineColor;
return o;

// Fragment: simply return the outline color
return i.color;

// URP Fresnel - Fragment calculation
float3 viewDirWS = normalize(_WorldSpaceCameraPos - IN.positionWS);
float3 normalWS = normalize(IN.normalWS);
float fresnel = pow(1.0 - saturate(dot(viewDirWS, normalWS)), _FresnelPower);
fresnel *= _FresnelIntensity;

half4 baseColor = SAMPLE_TEXTURE2D(_BaseMap, sampler_BaseMap, IN.uv);
return baseColor + _FresnelColor * fresnel;

// URP Toon - Lighting calculation in fragment
Light mainLight = GetMainLight(IN.shadowCoord);
float NdotL = dot(IN.normalWS, mainLight.direction);

// Quantize lighting into bands
float shadow = smoothstep(_ShadowThreshold - _ShadowSmoothness,
                          _ShadowThreshold + _ShadowSmoothness, NdotL);
half4 litColor = _BaseColor;
half4 shadColor = _ShadowColor * _BaseColor;
half4 finalColor = lerp(shadColor, litColor, shadow);

// Specular band
float3 halfDir = normalize(mainLight.direction + IN.viewDirWS);
float spec = step(1.0 - _SpecularSize, saturate(dot(IN.normalWS, halfDir)));
finalColor.rgb += spec * mainLight.color;

return finalColor;

// URP Water - Vertex displacement
float wave = sin(v.positionOS.x * 2.0 + _Time.y * _WaveSpeed)
           + cos(v.positionOS.z * 1.5 + _Time.y * _WaveSpeed * 0.8);
v.positionOS.y += wave * _WaveHeight * 0.5;

// Fragment - depth-based coloring
float sceneDepth = LinearEyeDepth(
    SAMPLE_TEXTURE2D(_CameraDepthTexture, sampler_CameraDepthTexture, screenUV).r,
    _ZBufferParams);
float surfaceDepth = IN.positionCS.w;
float depthDiff = saturate((sceneDepth - surfaceDepth) / _DepthMaxDistance);
half4 waterColor = lerp(_ShallowColor, _DeepColor, depthDiff);

// Scrolling normals
float2 uv1 = IN.uv + _Time.y * float2(0.03, 0.02);
float2 uv2 = IN.uv + _Time.y * float2(-0.02, 0.03);
float3 n1 = UnpackNormal(SAMPLE_TEXTURE2D(_NormalMap1, sampler_NormalMap1, uv1));
float3 n2 = UnpackNormal(SAMPLE_TEXTURE2D(_NormalMap2, sampler_NormalMap2, uv2));
float3 finalNormal = normalize(n1 + n2);

// URP Hologram - Fragment shader
float3 viewDirWS = normalize(_WorldSpaceCameraPos - IN.positionWS);
float fresnel = pow(1.0 - saturate(dot(viewDirWS, IN.normalWS)), _FresnelPower);

// Scan lines
float scanLine = step(0.5, frac(IN.positionWS.y * _ScanLineDensity
    + _Time.y * _ScanLineSpeed));

// Flicker
float flicker = 0.8 + 0.2 * step(0.9, frac(sin(_Time.y * _FlickerSpeed) * 43758.5453));

float alpha = (fresnel + scanLine * 0.3) * flicker;
half4 color = _HoloColor;
color.a = saturate(alpha);
return color;
